[
  {
    "ae_shared_affect": "made me tense too",
    "ce_mental_state_attribution": "I think you're uneasy about it",
    "pd_personal_consequence_anxiety": "I'm the one who gets frozen out at work",
    "sys_instrumental_norm_use": "split-it-evenly idea because it keeps people from turning on me"
  },
  {
    "ae_shared_affect": "I caught it and stayed wound up",
    "ce_mental_state_attribution": "she seemed stressed",
    "pd_personal_consequence_anxiety": "scared whatever I say gets repeated and I look petty",
    "sys_instrumental_norm_use": "back equal pay mostly because it saves me the fallout"
  },
  {
    "ae_shared_affect": "that worry landed right on me",
    "ce_mental_state_attribution": "You looked worried",
    "pd_personal_consequence_anxiety": "What if I recommend something and it blows up",
    "sys_instrumental_norm_use": "staying on good terms is what keeps me safe here"
  },
  {
    "ae_shared_affect": "rubbed off, so I'm edgy now too",
    "ce_mental_state_attribution": "you sounded on edge",
    "pd_personal_consequence_anxiety": "People talk, and I'd be the one blamed",
    "sys_instrumental_norm_use": "Equal treatment works for me as long as nobody ends up mad at me"
  },
  {
    "ae_shared_affect": "my own nerves spiked right along with yours",
    "ce_mental_state_attribution": "You seemed nervous",
    "pd_personal_consequence_anxiety": "worried I lose standing with the team",
    "sys_instrumental_norm_use": "stick to 'same work, same pay' because it protects me"
  },
  {
    "ae_shared_affect": "I got panicky right with her",
    "ce_mental_state_attribution": "she kept looking panicked",
    "pd_personal_consequence_anxiety": "that's a bad look for me, and I'm afraid of that",
    "sys_instrumental_norm_use": "push for equal payment if it keeps things smooth"
  },
  {
    "ae_shared_affect": "started feeling as anxious as you seemed",
    "ce_mental_state_attribution": "You asked so carefully",
    "pd_personal_consequence_anxiety": "scared of being seen as the person who controlled her money",
    "sys_instrumental_norm_use": "follow the fair-split thing when it spares me grief"
  },
  {
    "ae_shared_affect": "her tension fed mine",
    "ce_mental_state_attribution": "she was as tense as I was",
    "pd_decision_conflict": "I keep going back and forth, and I hate that",
    "pd_personal_consequence_anxiety": "could end up resented or gossiped about",
    "sys_instrumental_norm_use": "only because breaking that pattern would come back on me"
  },
  {
    "ae_shared_affect": "Now I'm uneasy too",
    "ce_mental_state_attribution": "You seemed uneasy",
    "pd_personal_consequence_anxiety": "I'd be the one paying for that socially",
    "sys_instrumental_norm_use": "keeping things even when it keeps me out of trouble"
  },
  {
    "ae_shared_affect": "by the end I felt just as frayed",
    "ce_mental_state_attribution": "her more than me at first",
    "pd_personal_consequence_anxiety": "afraid of getting this wrong and having it follow me",
    "sys_instrumental_norm_use": "follow because breaking them costs me"
  }
]
